export function tierForScore(score) {
 if (!Number.isInteger(score) || score < 0 || score > 125) throw new RangeError('El resultado debe estar entre 0 y 125 aciertos.');
 return tiers.find(tier => score >= tier.min && score <= tier.max);
}
